// ---------------------------------------------------------------------------
// Epic 11 B1 tests: TwoColors / CycleProfiles / SetColor
// ---------------------------------------------------------------------------

// Self-check: the Python port's TwoColors output for the existing
// red→green inputs MUST match the original jamesw343-derived reference.
// If this fails, tools/pixmob_parity_gen.py is broken and any other
// Epic 11 vector below is suspect.
static void test_python_port_self_check_against_existing(void) {
    TEST_ASSERT_EQUAL_size_t_MESSAGE(
        REF_TWO_COLORS_RED_THEN_GREEN_LEN,
        REF_TWO_COLORS_RED_GREEN_DUP_LEN,
        "Python port DUP and original have different pulse counts - "
        "tools/pixmob_parity_gen.py has drifted from jamesw343"
    );
    for (size_t i = 0; i < REF_TWO_COLORS_RED_THEN_GREEN_LEN; i++) {
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "Python port DUP differs from original at pulse[%zu]", i);
        TEST_ASSERT_EQUAL_UINT16_MESSAGE(
            REF_TWO_COLORS_RED_THEN_GREEN[i],
            REF_TWO_COLORS_RED_GREEN_DUP[i],
            msg
        );
    }
}

